  "implementation": "def solve(case):
    edges = case.get('edges')
    refinement = case.get('refinement')
    if not isinstance(edges, list) or not isinstance(refinement, dict):
        raise ValueError('Invalid case: edges and refinement required')
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 3:
            raise ValueError('Invalid edge format')
        u, v, w = e
        if not isinstance(u, str) or not isinstance(v, str) or not isinstance(w, (int, float)):
            raise ValueError('Invalid edge elements')
        if u not in refinement or v not in refinement:
            raise ValueError('Edge node not in refinement')
    members = {}
    for node, group in refinement.items():
        if not isinstance(node, str) or not isinstance(group, str):
            raise ValueError('Invalid refinement mapping')
        members.setdefault(group, []).append(node)
    for group in members:
        members[group].sort()
    edge_sums = {}
    for e in edges:
        u, v, w = e
        gu = refinement[u]
        gv = refinement[v]
        pair = (gu, gv) if gu <= gv else (gv, gu)
        edge_sums[pair] = edge_sums.get(pair, 0) + w
    aggregate_edges = []
    for (g1, g2), total in sorted(edge_sums.items()):
        aggregate_edges.append([g1, g2, total])
    return {'aggregate_edges': aggregate_edges, 'members': members}"
}
